body {
  background: #f4f7fb;
  font-family: Arial, sans-serif;
  margin: 0;
  padding: 40px;
}

.app-card {
  background: white;
  padding: 24px;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  max-width: 500px;
  margin: 0 auto;
}

.primary-button {
  background: #2563eb;
  color: white;
  padding: 12px 20px;
  border: none;
  border-radius: 8px;
  font-size: 16px;
}
